vector_search_common_patterns.overview:
Common code patterns and templates for vector search implementations
using Milvus and local Hugging Face (sentence-transformers) embeddings,
built on the helpers in common.py and schema.py.

pattern.code:
        
from typing import Dict, List

from pymilvus import MilvusClient

from schema import VECTOR_FIELD, product_text

def ingest_products(client: MilvusClient, collection_name: str, products: List[Dict], model) -> int:
    """Embed product_text() for each product and insert one row per product"""
    vectors = model.encode([product_text(p) for p in products], normalize_embeddings=True)
    rows = [
        {
            "product_name": p["product_name"],
            "price": p["price"],
            "category": p["category"],
            "description": p["description"],
            VECTOR_FIELD: vector,
        }
        for p, vector in zip(products, vectors.tolist())
    ]
    client.insert(collection_name=collection_name, data=rows)
    client.flush(collection_name=collection_name)
    return len(rows)
